/* GENERATED by gen_hcon_augmented.py -- models are generated.
   SAT_CLAIM_PA_DETAIL
   *** UNRATIFIED. This payload is a BUILD-SIDE PROPOSAL from the map's
   augmentation blocks and has NOT been ratified by the modeller. Attributes here
   are not declared on this satellite in data_7.js. Do not treat it as part of the
   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : SCD2
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 2 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_PA_DETAIL_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , CAUSE_OF_DEATH as CAUSE_OF_DEATH_DESCRIPTION
        , TRANSMORT_DATE as TRANSPORTATION_OF_MORTAL_REMAINS_DATE
        , 'BJAZ_HM_HCS_TECH_ASSESS_COV' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_hcs_tech_assess_cov') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then CAUSE_OF_DEATH_DESCRIPTION end) as CAUSE_OF_DEATH_DESCRIPTION,
        max(case when SOURCE_RUN = 'opus_health_v2' then TRANSPORTATION_OF_MORTAL_REMAINS_DATE end) as TRANSPORTATION_OF_MORTAL_REMAINS_DATE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when CAUSE_OF_DEATH_DESCRIPTION is not null or TRANSPORTATION_OF_MORTAL_REMAINS_DATE is not null
                     then md5(upper(coalesce(cast(CAUSE_OF_DEATH_DESCRIPTION as varchar), '') || '|' || coalesce(cast(TRANSPORTATION_OF_MORTAL_REMAINS_DATE as varchar), '')))
                end as SAT_CLAIM_PA_DETAIL_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_PA_DETAIL_HASHDIFF is not null
